-- A person's aliases: other names they are found by, stored trimmed. Aliases share the names'
-- uniqueness on a sheet, without regard to case: no alias equals another alias or any person's name
-- (the app checks the names; the index the aliases). Kept in person_alias_hist, as person_hold is.
CREATE TABLE person_alias (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(255) NOT NULL,
    person_id BIGINT       NOT NULL,
    alias     VARCHAR(255) NOT NULL,
    alias_key VARCHAR(255) GENERATED ALWAYS AS (LOWER(alias))
);
CREATE UNIQUE INDEX person_alias_sheet_key ON person_alias (sheet_id, alias_key);
CREATE INDEX person_alias_person ON person_alias (sheet_id, person_id);

CREATE TABLE person_alias_hist AS SELECT * FROM person_alias WITH NO DATA;
ALTER TABLE person_alias_hist ADD COLUMN hist_seq BIGINT NOT NULL;
ALTER TABLE person_alias_hist ADD COLUMN hist_made_on DATE NOT NULL;
ALTER TABLE person_alias_hist ADD COLUMN hist_gone BOOLEAN DEFAULT FALSE NOT NULL;
CREATE INDEX person_alias_hist_key ON person_alias_hist (id, hist_seq);
CREATE TRIGGER person_alias_history AFTER INSERT, UPDATE, DELETE ON person_alias FOR EACH ROW
    CALL 'net.officefloor.hq.app.history.HistoryTrigger';
-- The sheet's claim templates: a name (trimmed, at most once per sheet), the amount and the note a claim
-- made from one starts with. Saving a name again replaces its amount and note; a claim made from a
-- template copies them, so a later change leaves it as it was. Kept by version like the rest of the screen.
CREATE TABLE claim_template (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(255)   NOT NULL,
    name     VARCHAR(1000)  NOT NULL,
    amount   DECIMAL(19, 2) NOT NULL,
    note     VARCHAR(4000)  NOT NULL,
    UNIQUE (sheet_id, name)
);

CREATE TABLE claim_template_hist AS SELECT * FROM claim_template WITH NO DATA;
ALTER TABLE claim_template_hist ADD COLUMN hist_seq BIGINT NOT NULL;
ALTER TABLE claim_template_hist ADD COLUMN hist_made_on DATE NOT NULL;
ALTER TABLE claim_template_hist ADD COLUMN hist_gone BOOLEAN DEFAULT FALSE NOT NULL;
CREATE INDEX claim_template_hist_key ON claim_template_hist (id, hist_seq);
CREATE TRIGGER claim_template_history AFTER INSERT, UPDATE, DELETE ON claim_template FOR EACH ROW
    CALL 'net.officefloor.hq.app.history.HistoryTrigger';
-- The sheet's pools: a name (trimmed, at most once per sheet) and its members, each a person on the sheet
-- (at most once per pool) with a share percent (two decimals, more than 0 and at most 100). A person may be
-- in several pools. Kept by version like the rest of the screen.
CREATE TABLE pool (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(255)  NOT NULL,
    name     VARCHAR(1000) NOT NULL,
    UNIQUE (sheet_id, name)
);

CREATE TABLE pool_member (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(255)  NOT NULL,
    pool_id   BIGINT        NOT NULL,
    person_id BIGINT        NOT NULL,
    share     DECIMAL(5, 2) NOT NULL,
    UNIQUE (pool_id, person_id)
);

CREATE TABLE pool_hist AS SELECT * FROM pool WITH NO DATA;
ALTER TABLE pool_hist ADD COLUMN hist_seq BIGINT NOT NULL;
ALTER TABLE pool_hist ADD COLUMN hist_made_on DATE NOT NULL;
ALTER TABLE pool_hist ADD COLUMN hist_gone BOOLEAN DEFAULT FALSE NOT NULL;
CREATE INDEX pool_hist_key ON pool_hist (id, hist_seq);
CREATE TRIGGER pool_history AFTER INSERT, UPDATE, DELETE ON pool FOR EACH ROW
    CALL 'net.officefloor.hq.app.history.HistoryTrigger';

CREATE TABLE pool_member_hist AS SELECT * FROM pool_member WITH NO DATA;
ALTER TABLE pool_member_hist ADD COLUMN hist_seq BIGINT NOT NULL;
ALTER TABLE pool_member_hist ADD COLUMN hist_made_on DATE NOT NULL;
ALTER TABLE pool_member_hist ADD COLUMN hist_gone BOOLEAN DEFAULT FALSE NOT NULL;
CREATE INDEX pool_member_hist_key ON pool_member_hist (id, hist_seq);
CREATE TRIGGER pool_member_history AFTER INSERT, UPDATE, DELETE ON pool_member FOR EACH ROW
    CALL 'net.officefloor.hq.app.history.HistoryTrigger';
-- A person's patrons: other people on the same sheet they named, each at most once.
CREATE TABLE patron (
    sheet_id  VARCHAR(255) NOT NULL,
    person_id BIGINT       NOT NULL,
    patron_id BIGINT       NOT NULL,
    PRIMARY KEY (sheet_id, person_id, patron_id)
);
-- Who watches whom: a user watching a person on the sheet, each at most once. The id orders a person's
-- watchers by when they started watching; watching again after stopping starts afresh.
CREATE TABLE watch (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(255) NOT NULL,
    person_id BIGINT       NOT NULL,
    username  VARCHAR(255) NOT NULL,
    UNIQUE (sheet_id, person_id, username)
);
-- A person's statements: each records their due-total at that moment (null when it was n/a), how
-- many of their claims counted then, and the sheet's today when it was taken. Listed by id.
CREATE TABLE statement (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(255)   NOT NULL,
    person_id BIGINT         NOT NULL,
    taken_on  DATE           NOT NULL,
    due_total DECIMAL(19, 2),
    claims    INT            NOT NULL,
    taken_by  VARCHAR(255)
);
CREATE INDEX statement_person ON statement (sheet_id, person_id, id);
-- A claim bound by its person's last statement: it shows and totals stated_due (the figure it had
-- then; null when it had none, n/a) until their next statement rebinds or unbinds it.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(19, 2);
-- A person's claims: an amount (0.00 or more, two decimals), a date and a note (may be empty).
-- Listed newest first (by id).
CREATE TABLE claim (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(255)   NOT NULL,
    person_id  BIGINT         NOT NULL,
    amount     DECIMAL(19, 2) NOT NULL,
    claim_date DATE           NOT NULL,
    note       VARCHAR(4000)  NOT NULL
);
CREATE INDEX claim_sheet ON claim (sheet_id, person_id, id);
-- A claim's number: given when it is opened, the next on its sheet (1, 2, ...), never reused.
-- A draft has none, and voiding a claim clears it.
ALTER TABLE claim ADD COLUMN number BIGINT;
-- The last number given on each sheet. Its row is locked while a number is taken, so two claims
-- opened at once get different numbers.
CREATE TABLE claim_number (
    sheet_id    VARCHAR(255) PRIMARY KEY,
    last_number BIGINT NOT NULL
);
-- A claim's number is now text: the sheet-wide 1, 2, ... as before, or, while the sheet numbers by
-- period, <period name>-<n> (X-<n> for a claim in no period). A correction names it the same way.
ALTER TABLE claim ALTER COLUMN number VARCHAR(255);
ALTER TABLE claim ALTER COLUMN corrects VARCHAR(255);
-- The last number given in each per-period sequence on a sheet ('P:<period name>', or 'X' for claims
-- in no period). Locked while a number is taken, as claim_number is.
CREATE TABLE claim_period_number (
    sheet_id    VARCHAR(255) NOT NULL,
    sequence    VARCHAR(255) NOT NULL,
    last_number BIGINT NOT NULL,
    PRIMARY KEY (sheet_id, sequence)
);
-- Where a claim is listed among its person's claims, newest first: taken when it is added, and taken
-- anew when it is moved to another person, so it is listed as their newest claim whatever its date.
CREATE SEQUENCE claim_listed_seq;
ALTER TABLE claim ADD COLUMN listed BIGINT DEFAULT NEXT VALUE FOR claim_listed_seq NOT NULL;
CREATE INDEX claim_sheet_listed ON claim (sheet_id, listed);
