package net.officefloor.hq.app.role;

import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.history.History;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.sheet.SheetStore;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The roles assigned per sheet. A user name with none assigned is a clerk; one with a delegation of the
 *  steward role in force on the sheet's today acts as a steward (see {@link DelegationStore}). */
@Repository
public class RoleStore {

    private final JdbcTemplate jdbc;
    private final DelegationStore delegations;
    private final SheetStore sheets;

    public RoleStore(JdbcTemplate jdbc, DelegationStore delegations, SheetStore sheets) {
        this.jdbc = jdbc;
        this.delegations = delegations;
        this.sheets = sheets;
    }

    /** Every role assigned on the sheet, by user name. */
    public List<RoleResponse> list(String sheetId) {
        return listFrom(sheetId, "sheet_role");
    }

    /** Every role assigned on the sheet at the end of the date (see {@link History}), by user name. */
    public List<RoleResponse> listAsOf(String sheetId, LocalDate date) {
        return listFrom(sheetId, History.asOf("sheet_role", "sheet_id, user_name", date));
    }

    private List<RoleResponse> listFrom(String sheetId, String table) {
        return jdbc.query("SELECT user_name, role FROM " + table + " WHERE sheet_id = ? ORDER BY user_name",
                (rs, i) -> new RoleResponse(rs.getString("user_name"), Role.valueOf(rs.getString("role")).shown()),
                sheetId);
    }

    /** The role the user acts in on the sheet: steward while a delegation to them is in force, else
     *  the role assigned. */
    public Role find(String sheetId, String user) {
        return delegations.delegator(sheetId, user) != null ? Role.STEWARD : assigned(sheetId, user);
    }

    /** The user's role as assigned on the sheet, delegations aside: clerk unless assigned otherwise. */
    public Role assigned(String sheetId, String user) {
        List<String> found = jdbc.queryForList("SELECT role FROM sheet_role WHERE sheet_id = ? AND user_name = ?",
                String.class, sheetId, user);
        return found.isEmpty() ? Role.CLERK : Role.valueOf(found.get(0));
    }

    /** Refuses any change to an archived sheet, and any change by a viewer: a viewer may change nothing
     *  on the sheet. */
    public void refuseChange(String sheetId, String user) throws InvalidSheetException {
        sheets.refuseArchived(sheetId);
        if (find(sheetId, user == null ? "" : user.trim()) == Role.VIEWER) {
            throw new InvalidSheetException("A viewer may change nothing");
        }
    }

    public void set(String sheetId, String user, Role role) {
        jdbc.update("MERGE INTO sheet_role (sheet_id, user_name, role) KEY (sheet_id, user_name) VALUES (?, ?, ?)",
                sheetId, user, role.name());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.person.Retirement;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Refuses a claim's move unless a role the sheet's permission matrix allows to reassign (by
 *  default a steward) moves a DRAFT, OPEN or PENDING claim that is not a
 *  correction to another person on the sheet, who is not retired from before the claim's date. */
public class CheckReassign {
    public void check(@Val ReassignInput input, @Val Claim claim, RoleStore roles, PersonStore people,
            SettingStore settings, Out<Reassignment> reassignment) throws InvalidSheetException {
        reassignment.set(refuse(input, claim, roles, people, settings, false));
    }

    /** The move, or refused as a single move is; a bulk move lets a claim "move" to the person it is with. */
    static Reassignment refuse(ReassignInput input, Claim claim, RoleStore roles, PersonStore people,
            SettingStore settings, boolean bulk) throws InvalidSheetException {
        Role role = roles.find(claim.getSheetId(), input.user());
        if (!settings.allows(claim.getSheetId(), "reassign", role)) {
            throw new InvalidSheetException("A " + role.shown() + " may not move a claim");
        }
        if (!claim.getStatus().canMove()) {
            throw new InvalidSheetException("A " + claim.getStatus() + " claim cannot move");
        }
        if (claim.isCorrection()) {
            throw new InvalidSheetException("A correction stays with the claim it corrects");
        }
        Person from = people.find(claim.getSheetId(), claim.getPersonId());
        Person to = people.find(claim.getSheetId(), input.to());
        if (to == null) {
            throw new InvalidSheetException("No such person: " + input.to());
        }
        if (!bulk && to.getId() == claim.getPersonId()) {
            throw new InvalidSheetException("The claim is already " + to.getName() + "'s");
        }
        Retirement.refuseClaimDate(to, claim.getDate());
        return new Reassignment(from, to);
    }
}

