package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Names the patron as the person's, refusing themselves, someone not on the sheet, or a patron twice. */
public class AddPatron {
    public void add(@Val PatronRequest request, @Val Person person, PersonStore people, PatronStore patrons,
            Out<Patron> added) throws InvalidSheetException {
        Person patron = request.patronId() == null ? null : people.find(person.getSheetId(), request.patronId());
        if (patron == null) {
            throw new InvalidSheetException("No such person to be a patron");
        }
        if (patron.getId() == person.getId()) {
            throw new InvalidSheetException("A person cannot be their own patron");
        }
        if (patrons.of(person.getSheetId(), person.getId()).contains(patron.getId())) {
            throw new InvalidSheetException(patron.getName() + " is already a patron");
        }
        patrons.add(person.getSheetId(), person.getId(), patron.getId());
        added.set(new Patron(patron));
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.history.History;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** Each person's patrons, kept per sheet as the ids of the people they named. */
@Repository
public class PatronStore {

    private final JdbcTemplate jdbc;

    public PatronStore(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The ids of each person's patrons on the sheet, keyed by the person's id. */
    public Map<Long, List<Long>> all(String sheetId) {
        return allFrom(sheetId, "patron");
    }

    /** The ids of each person's patrons on the sheet as they stood at the end of the date (see {@link History}). */
    public Map<Long, List<Long>> allAsOf(String sheetId, LocalDate date) {
        return allFrom(sheetId, History.asOf("patron", "sheet_id, person_id, patron_id", date));
    }

    private Map<Long, List<Long>> allFrom(String sheetId, String table) {
        Map<Long, List<Long>> found = new HashMap<>();
        jdbc.query("SELECT person_id, patron_id FROM " + table + " WHERE sheet_id = ? ORDER BY patron_id",
                rs -> {
                    found.computeIfAbsent(rs.getLong("person_id"), k -> new ArrayList<>()).add(rs.getLong("patron_id"));
                }, sheetId);
        return found;
    }

    public List<Long> of(String sheetId, long personId) {
        return jdbc.queryForList("SELECT patron_id FROM patron WHERE sheet_id = ? AND person_id = ? ORDER BY patron_id",
                Long.class, sheetId, personId);
    }

    public void add(String sheetId, long personId, long patronId) {
        jdbc.update("INSERT INTO patron (sheet_id, person_id, patron_id) VALUES (?, ?, ?)", sheetId, personId, patronId);
    }
}
